#include "Vrecam_resource_aware_fallback_selector.h"
#include <cstdint>
#include <iostream>
static void clear(Vrecam_resource_aware_fallback_selector&d){for(auto&w:d.config_pattern_map_i)w=0;d.resource_released_i=0;d.resource_borrower_flat_i=0;}
static void put(Vrecam_resource_aware_fallback_selector&d,unsigned i,unsigned cfg,unsigned pat,unsigned cand){unsigned b=i*20,w=b/32,o=b%32;std::uint64_t x=(std::uint64_t(cand)<<10)|(std::uint64_t(pat)<<6)|(1ull<<5)|(1ull<<4)|(std::uint64_t(cfg)<<1)|1;d.config_pattern_map_i[w]|=x<<o;if(o>12)d.config_pattern_map_i[w+1]|=x>>(32-o);}
static bool sel(Vrecam_resource_aware_fallback_selector&d,unsigned idx,unsigned cfg,unsigned donor,bool borrow,bool release,unsigned rel){d.eval();return d.physical_solution_valid_o&&d.selected_map_index_o==idx&&d.selected_config_id_o==cfg&&d.selected_donor_valid_o==borrow&&(!borrow||d.selected_donor_resource_o==donor)&&d.release_required_o==release&&(!release||d.release_resource_o==rel)&&d.selected_pattern_id_o==idx+1&&d.selected_candidate_valid_o==(1u<<idx);}
int main(){Vrecam_resource_aware_fallback_selector d;d.sa_id_i=0;d.policy_i=0;clear(d);put(d,0,0,1,1);if(!sel(d,0,0,0,0,0,0))return 1;std::cout<<"G-E1 PASS\n";clear(d);put(d,2,5,3,4);put(d,3,6,4,8);d.eval();if(d.physical_solution_valid_o)return 1;std::cout<<"G-E2 PASS\n";d.resource_released_i=4; if(!sel(d,2,5,2,1,0,0))return 1;std::cout<<"G-E3/A DONOR PASS\n";d.policy_i=1;clear(d);put(d,0,0,1,1);put(d,1,4,2,2);if(!sel(d,1,4,0,0,1,0))return 1;std::cout<<"G-G1 PASS\n";clear(d);put(d,1,4,2,2);put(d,2,5,3,4);d.resource_released_i=0;if(!sel(d,1,4,0,0,1,0))return 1;std::cout<<"G-G2 FALLBACK PASS\n";clear(d);put(d,2,5,3,4);put(d,3,6,4,8);d.resource_released_i=12;if(!sel(d,3,6,2,1,1,0))return 1;std::cout<<"G-G3 PASS\n";clear(d);put(d,2,5,3,4);d.resource_released_i=4;d.resource_borrower_flat_i=1u<<4;d.eval();if(d.physical_solution_valid_o)return 1;d.resource_released_i=12;if(!sel(d,2,5,3,1,0,0))return 1;std::cout<<"ALLOCATED DONOR PROTECTION PASS\n";d.sa_id_i=3;clear(d);put(d,2,5,3,4);d.resource_released_i=12;if(!sel(d,2,5,3,1,0,0))return 1;std::cout<<"D MIRROR DONOR PASS\n";d.sa_id_i=1;clear(d);put(d,1,2,2,2);d.resource_released_i=3;if(!sel(d,1,2,0,1,0,0))return 1;std::cout<<"B ROW DONOR PASS\n";d.sa_id_i=2;clear(d);put(d,1,2,2,2);d.resource_released_i=3;if(!sel(d,1,2,1,1,0,0))return 1;std::cout<<"C ROW DONOR PASS\n";d.resource_borrower_flat_i=3;d.eval();if(d.physical_solution_valid_o||d.physical_feasible_bitmap_o)return 1;std::cout<<"INVALID LEDGER PASS\nPHASE3G_RESOURCE_FALLBACK_REGRESSION PASS\n";}
